INSERT INTO `rpa_process_step` VALUES (30,3,1,'测试步骤01','ACTION','Groovy','return \"步骤执行成功\"',NULL,NULL,'2026-03-25 17:26:31','2026-03-25 17:26:31'),(31,3,2,'测试步骤02','ACTION','Groovy','println \"taskId=\" + taskId\nprintln \"taskCode=\" + taskCode\nreturn \"任务[\" + taskCode + \"]执行成功\"',NULL,NULL,'2026-03-25 17:26:31','2026-03-25 17:26:31'),(32,3,3,'测试步骤03','ACTION','Groovy','def result = [\n    taskId: taskId,\n    taskCode: taskCode,\n    taxpayerIdNo: taxpayerIdNo,\n    robotCode: robotCode,\n    stepName: stepName\n]\nreturn result.toString()',NULL,NULL,'2026-03-25 17:26:31','2026-03-25 17:26:31'),(33,1,1,'登录税务系统','ACTION','Groovy','if (page == null) throw new RuntimeException(\"未注入 page\")\nif (!baseUrl) throw new RuntimeException(\"未提供 baseUrl\")\nif (!enterpriseName) throw new RuntimeException(\"未提供 enterpriseName\")\nif (!appDate) throw new RuntimeException(\"未提供 appDate\")\n\ndef payload = [\n    enterpriseName: enterpriseName,\n    taxNo: \"\",\n    uscCode: \"\",\n    appDate: \"\",\n    invoices: []\n]\n\ndef safeText = { String selector ->\n    try {\n        page.locator(selector).first().innerText().trim()\n    } catch (Exception ignored) {\n        \"\"\n    }\n}\n\npage.navigate(baseUrl + \"/enterprise-info\")\npage.waitForSelector(\"#enterprise-name-input\")\npage.fill(\"#enterprise-name-input\", enterpriseName)\npage.locator(\'button:has-text(\"查询\")\').first().click()\npage.waitForSelector(\"#tax-no\")\n\npayload.taxNo = safeText(\"#tax-no\")\npayload.uscCode = safeText(\"#usc-code\")\n\npage.navigate(baseUrl + \"/application\")\npage.waitForSelector(\"#app-tax-no\")\npage.fill(\"#app-tax-no\", payload.taxNo)\npage.fill(\"#app-usc-code\", payload.uscCode)\npage.fill(\"#app-date\", appDate)\npage.selectOption(\"#app-type\", \"credit\")\npage.locator(\'button[type=\"submit\"]:has-text(\"提交申请\")\').click()\npage.waitForSelector(\"#app-date-display\")\npayload.appDate = safeText(\"#app-date-display\")\n\npage.navigate(baseUrl + \"/invoice-query\")\npage.waitForSelector(\"#invoice-tax-no\")\npage.fill(\"#invoice-tax-no\", payload.taxNo)\npage.fill(\"#invoice-usc-code\", payload.uscCode)\npage.locator(\'button:has-text(\"查询\")\').first().click()\npage.waitForSelector(\"tbody tr\")\n\nint rowCount = page.locator(\"tbody tr\").count()\nfor (int i = 0; i < rowCount; i++) {\n    payload.invoices << [\n        sign: safeText(\"#invoice-sign-${i}\"),\n        state: safeText(\"#invoice-state-${i}\"),\n        invoiceTime: safeText(\"#invoice-time-${i}\"),\n        jshjText: safeText(\"#invoice-jshj-${i}\")\n    ]\n}\n\nreturn payload',NULL,NULL,'2026-03-25 17:51:42','2026-03-25 17:51:42'),(34,1,2,'02','ACTION','Groovy','import java.time.LocalDate\nimport java.time.LocalDateTime\nimport java.time.format.DateTimeFormatter\n\nif (!rawData) throw new RuntimeException(\"未提供 rawData\")\n\ndef appFmt = DateTimeFormatter.ofPattern(\"yyyy-MM-dd\")\ndef invoiceFmt = DateTimeFormatter.ofPattern(\"yyyy-MM-dd HH:mm:ss\")\n\nMap payload = rawData instanceof Map ? rawData : new groovy.json.JsonSlurper().parseText(String.valueOf(rawData))\n\ndef appDate = LocalDate.parse(String.valueOf(payload.appDate), appFmt)\n\ndef invoices = (payload.invoices ?: []).collect { row ->\n    def item = [\n        sign: row.sign,\n        state: row.state,\n        invoiceTime: row.invoiceTime,\n        jshjText: row.jshjText\n    ]\n    try {\n        def invoiceTime = LocalDateTime.parse(String.valueOf(row.invoiceTime), invoiceFmt)\n        int diff = (appDate.year - invoiceTime.year) * 12 + (appDate.monthValue - invoiceTime.monthValue)\n        item.invoiceTimeParsed = invoiceTime.toString()\n        item.monthDiffToAppDate = diff\n    } catch (Exception ignored) {\n    }\n    item\n}\n\nreturn [\n    enterpriseName: payload.enterpriseName,\n    taxNo: payload.taxNo,\n    uscCode: payload.uscCode,\n    appDate: payload.appDate,\n    invoices: invoices\n]',NULL,NULL,'2026-03-25 17:51:42','2026-03-25 17:51:42'),(35,1,3,'03','ACTION','Groovy','if (jdbcTemplate == null) throw new RuntimeException(\"未注入 jdbcTemplate\")\nif (objectMapper == null) throw new RuntimeException(\"未注入 objectMapper\")\nif (!taskId) throw new RuntimeException(\"未提供 taskId\")\nif (!taxNo) throw new RuntimeException(\"未提供 taxNo\")\nif (!enterpriseName) throw new RuntimeException(\"未提供 enterpriseName\")\nif (result == null) throw new RuntimeException(\"未提供 result\")\n\ndef businessData = [\n        indicatorCode : indicatorCode,\n        taskId        : taskId,\n        enterpriseName: enterpriseName,\n        taxNo         : taxNo,\n        result        : result,\n        collectionId  : collectionId,\n        parsingId     : parsingId,\n        processingId  : processingId\n]\n\njdbcTemplate.update(\"\"\"\n    insert into rpa_data_query\n    (task_id, tax_no, enterprise_name, category_id, business_data, data_status, deleted)\n    values (?, ?, ?, ?, ?, ?, ?)\n\"\"\", taskId, taxNo, enterpriseName, null, objectMapper.writeValueAsString(businessData), \"available\", 0)\n\nreturn businessData',NULL,NULL,'2026-03-25 17:51:42','2026-03-25 17:51:42'),(36,1,4,'04','ACTION','Groovy','import java.math.BigDecimal\nimport java.math.RoundingMode\nimport java.time.LocalDate\nimport java.time.LocalDateTime\nimport java.time.YearMonth\nimport java.time.format.DateTimeFormatter\n\nif (!parsedData) throw new RuntimeException(\"未提供 parsedData\")\nif (!indicatorCode) throw new RuntimeException(\"未提供 indicatorCode\")\n\ndef appFmt = DateTimeFormatter.ofPattern(\"yyyy-MM-dd\")\ndef invoiceFmt = DateTimeFormatter.ofPattern(\"yyyy-MM-dd HH:mm:ss\")\n\nMap parsed = parsedData as Map\ndef appDate = LocalDate.parse(String.valueOf(parsed.appDate), appFmt)\ndef invoices = (parsed.invoices ?: []) as List<Map>\n\nBigDecimal sum = BigDecimal.ZERO\nint total = 0\nint matched = 0\nList<Map> matchedInvoices = []\n\nBigDecimal parseMoney(Object text) {\n    if (text == null) return BigDecimal.ZERO\n    String cleaned = String.valueOf(text).trim().replace(\",\", \"\")\n    if (!cleaned) return BigDecimal.ZERO\n    try {\n        return new BigDecimal(cleaned)\n    } catch (Exception ignored) {\n        return BigDecimal.ZERO\n    }\n}\n\nboolean inWindow(LocalDate appDateValue, LocalDateTime invoiceTimeValue) {\n    def appYm = YearMonth.from(appDateValue)\n    def invYm = YearMonth.from(invoiceTimeValue)\n    int diff = (appYm.year - invYm.year) * 12 + (appYm.monthValue - invYm.monthValue)\n    return diff >= 1 && diff <= 12\n}\n\ninvoices.each { inv ->\n    total++\n    if (String.valueOf(inv.sign) != \"销项\") return\n    if (String.valueOf(inv.state) != \"正常\") return\n\n    LocalDateTime invoiceTime\n    try {\n        invoiceTime = LocalDateTime.parse(String.valueOf(inv.invoiceTime), invoiceFmt)\n    } catch (Exception ignored) {\n        return\n    }\n\n    if (!inWindow(appDate, invoiceTime)) return\n\n    def amount = parseMoney(inv.jshjText)\n    sum = sum.add(amount)\n    matched++\n    matchedInvoices << [\n        sign: inv.sign,\n        state: inv.state,\n        invoiceTime: inv.invoiceTime,\n        jshj: amount\n    ]\n}\n\nreturn [\n    processed: [\n        indicatorCode: indicatorCode,\n        sale_jshj_sum: sum.setScale(5, RoundingMode.HALF_UP),\n        appDate: parsed.appDate,\n        windowRule: \"近1-12个月(不含当月)\"\n    ],\n    validation: [\n        invoiceTotal: total,\n        invoiceMatched: matched,\n        matchedInvoices: matchedInvoices\n    ]\n]',NULL,NULL,'2026-03-25 17:51:42','2026-03-25 17:51:42'),(37,4,1,'单步骤测试','ACTION','Groovy','def baseUrl = \"http://study.zmyfrank.com:18010/spider/#\"\ndef appDate = \"2026-03-26\"\n\ndef safeText = { String selector ->\n    try {\n        return page.locator(selector).first().innerText().trim()\n    } catch (Exception ignored) {\n        return \"\"\n    }\n}\n\npage.navigate(baseUrl + \"/enterprise-info\")\npage.waitForSelector(\"#enterprise-name-input\")\npage.fill(\"#enterprise-name-input\", enterpriseName)\npage.locator(\'button:has-text(\"查询\")\').first().click()\npage.waitForSelector(\"#tax-no\")\n\ndef payload = [\n    enterpriseName: enterpriseName,\n    taxNo: safeText(\"#tax-no\"),\n    uscCode: safeText(\"#usc-code\"),\n    appDate: appDate\n]\n\npage.navigate(baseUrl + \"/invoice-query\")\npage.waitForSelector(\"#invoice-tax-no\")\npage.fill(\"#invoice-tax-no\", payload.taxNo)\npage.fill(\"#invoice-usc-code\", payload.uscCode)\npage.locator(\'button:has-text(\"查询\")\').first().click()\npage.waitForSelector(\"tbody tr\")\n\ndef invoices = []\nint rowCount = page.locator(\"tbody tr\").count()\nfor (int i = 0; i < rowCount; i++) {\n    invoices << [\n        sign: safeText(\"#invoice-sign-${i}\"),\n        state: safeText(\"#invoice-state-${i}\"),\n        invoiceTime: safeText(\"#invoice-time-${i}\"),\n        jshjText: safeText(\"#invoice-jshj-${i}\")\n    ]\n}\n\npayload.invoices = invoices\nreturn payload',NULL,NULL,'2026-03-26 10:28:06','2026-03-26 10:28:06'),(60,5,1,'采集发票数据','ACTION','Groovy','import org.springframework.jdbc.support.GeneratedKeyHolder\nimport java.sql.Statement\nimport java.sql.Timestamp\nimport java.time.LocalDateTime\n\ndef baseUrl = \"http://study.zmyfrank.com:18010/spider/#\"\ndef appDate = \"2024-02-06\"\ndef now = LocalDateTime.now()\n\ndef safeText = { String selector ->\n    try {\n        return page.locator(selector).first().innerText().trim()\n    } catch (Exception ignored) {\n        return \"\"\n    }\n}\n\npage.navigate(baseUrl + \"/enterprise-info\")\npage.waitForSelector(\"#enterprise-name-input\")\npage.fill(\"#enterprise-name-input\", enterpriseName)\npage.locator(\'button:has-text(\"查询\")\').first().click()\npage.waitForSelector(\"#tax-no\")\n\ndef payload = [\n    enterpriseName: enterpriseName,\n    taxNo: safeText(\"#tax-no\"),\n    uscCode: safeText(\"#usc-code\"),\n    appDate: appDate\n]\n\npage.navigate(baseUrl + \"/invoice-query\")\npage.waitForSelector(\"#invoice-tax-no\")\npage.fill(\"#invoice-tax-no\", payload.taxNo)\npage.fill(\"#invoice-usc-code\", payload.uscCode)\npage.locator(\'button:has-text(\"查询\")\').first().click()\npage.waitForSelector(\"tbody tr\")\n\ndef invoices = []\nint rowCount = page.locator(\"tbody tr\").count()\nfor (int i = 0; i < rowCount; i++) {\n    invoices << [\n        sign: safeText(\"#invoice-sign-${i}\"),\n        state: safeText(\"#invoice-state-${i}\"),\n        invoiceTime: safeText(\"#invoice-time-${i}\"),\n        jshjText: safeText(\"#invoice-jshj-${i}\")\n    ]\n}\n\npayload.invoices = invoices\n\ndef sql = \"\"\"\n    insert into data_collection\n    (task_id, execution_id, taxpayer_id_no, enterprise_name, source_name, status, raw_data, error_message, collect_time, collection_time, create_time, update_time)\n    values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n\"\"\"\n\ndef keyHolder = new GeneratedKeyHolder()\njdbcTemplate.update({ con ->\n    def ps = con.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)\n    ps.setLong(1, taskId as Long)\n    ps.setLong(2, executionId as Long)\n    ps.setString(3, taxpayerIdNo)\n    ps.setString(4, enterpriseName)\n    ps.setString(5, \"study-spider-demo\")\n    ps.setInt(6, 1)\n    ps.setString(7, objectMapper.writeValueAsString(payload))\n    ps.setString(8, null)\n    ps.setTimestamp(9, Timestamp.valueOf(now))\n    ps.setTimestamp(10, Timestamp.valueOf(now))\n    ps.setTimestamp(11, Timestamp.valueOf(now))\n    ps.setTimestamp(12, Timestamp.valueOf(now))\n    return ps\n}, keyHolder)\n\ndef collectionId = keyHolder.key?.longValue()\nif (collectionId == null) {\n    throw new RuntimeException(\"插入 data_collection 失败，未获取到主键\")\n}\n\nstepContext.collected = payload\nstepContext.collectionId = collectionId\n\nreturn [\n    collectionId: collectionId,\n    invoiceCount: invoices.size(),\n    taxpayerIdNo: taxpayerIdNo\n]',NULL,NULL,'2026-03-26 14:32:25','2026-03-26 14:32:25'),(61,5,2,'解析发票数据','ACTION','Groovy','import org.springframework.jdbc.support.GeneratedKeyHolder\nimport java.sql.Statement\nimport java.sql.Timestamp\nimport java.time.LocalDate\nimport java.time.LocalDateTime\nimport java.time.format.DateTimeFormatter\n\ndef payload = stepContext.collected ?: stepContext.step_1\nif (payload == null) {\n    throw new RuntimeException(\"未获取到采集结果\")\n}\nif (stepContext.collectionId == null) {\n    throw new RuntimeException(\"缺少 collectionId\")\n}\n\ndef appDate = LocalDate.parse(String.valueOf(payload.appDate), DateTimeFormatter.ofPattern(\"yyyy-MM-dd\"))\n\ndef invoices = (payload.invoices ?: []).collect { row ->\n    def item = [\n        sign: row.sign,\n        state: row.state,\n        invoiceTime: row.invoiceTime,\n        jshjText: row.jshjText\n    ]\n    try {\n        def parsedTime = LocalDateTime.parse(String.valueOf(row.invoiceTime), DateTimeFormatter.ofPattern(\"yyyy-MM-dd HH:mm:ss\"))\n        int diff = (appDate.year - parsedTime.year) * 12 + (appDate.monthValue - parsedTime.monthValue)\n        item.invoiceTimeParsed = parsedTime.toString()\n        item.monthDiffToAppDate = diff\n    } catch (Exception ignored) {\n    }\n    return item\n}\n\ndef parsed = [\n    enterpriseName: payload.enterpriseName,\n    taxNo: payload.taxNo,\n    uscCode: payload.uscCode,\n    appDate: payload.appDate,\n    invoices: invoices\n]\n\ndef now = LocalDateTime.now()\ndef sql = \"\"\"\n    insert into data_analysis\n    (task_id, execution_id, collection_id, taxpayer_id_no, enterprise_name, status, extracted_field_count, rule_name, parsed_data, error_message, analysis_time, create_time, update_time)\n    values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n\"\"\"\n\ndef keyHolder = new GeneratedKeyHolder()\njdbcTemplate.update({ con ->\n    def ps = con.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)\n    ps.setLong(1, taskId as Long)\n    ps.setLong(2, executionId as Long)\n    ps.setLong(3, stepContext.collectionId as Long)\n    ps.setString(4, taxpayerIdNo)\n    ps.setString(5, enterpriseName)\n    ps.setInt(6, 1)\n    ps.setInt(7, invoices.size())\n    ps.setString(8, \"发票解析规则\")\n    ps.setString(9, objectMapper.writeValueAsString(parsed))\n    ps.setString(10, null)\n    ps.setTimestamp(11, Timestamp.valueOf(now))\n    ps.setTimestamp(12, Timestamp.valueOf(now))\n    ps.setTimestamp(13, Timestamp.valueOf(now))\n    return ps\n}, keyHolder)\n\ndef analysisId = keyHolder.key?.longValue()\nif (analysisId == null) {\n    throw new RuntimeException(\"插入 data_analysis 失败，未获取到主键\")\n}\n\nstepContext.parsed = parsed\nstepContext.analysisId = analysisId\n\nreturn [\n    analysisId: analysisId,\n    extractedFieldCount: invoices.size()\n]',NULL,NULL,'2026-03-26 14:32:25','2026-03-26 14:32:25'),(62,5,3,'统计近12个月销项金额','ACTION','Groovy','import org.springframework.jdbc.support.GeneratedKeyHolder\nimport java.math.BigDecimal\nimport java.math.RoundingMode\nimport java.sql.Statement\nimport java.sql.Timestamp\nimport java.time.LocalDate\nimport java.time.LocalDateTime\nimport java.time.format.DateTimeFormatter\n\ndef parsed = stepContext.parsed ?: stepContext.step_2\nif (parsed == null) {\n    throw new RuntimeException(\"未获取到解析结果\")\n}\nif (stepContext.analysisId == null) {\n    throw new RuntimeException(\"缺少 analysisId\")\n}\n\ndef appDate = LocalDate.parse(String.valueOf(parsed.appDate), DateTimeFormatter.ofPattern(\"yyyy-MM-dd\"))\ndef invoices = parsed.invoices ?: []\n\ndef parseMoney = { value ->\n    if (value == null) {\n        return BigDecimal.ZERO\n    }\n    def cleaned = String.valueOf(value).trim().replace(\",\", \"\")\n    if (!cleaned) {\n        return BigDecimal.ZERO\n    }\n    try {\n        return new BigDecimal(cleaned)\n    } catch (Exception ignored) {\n        return BigDecimal.ZERO\n    }\n}\n\ndef isInPrevious12Months = { LocalDate app, LocalDateTime invoiceTime ->\n    int diff = (app.year - invoiceTime.year) * 12 + (app.monthValue - invoiceTime.monthValue)\n    return diff >= 1 && diff <= 12\n}\n\nBigDecimal sum = BigDecimal.ZERO\nint total = 0\nint matched = 0\ndef matchedInvoices = []\n\ninvoices.each { inv ->\n    total++\n    if (String.valueOf(inv.sign) != \"销项\") {\n        return\n    }\n    if (String.valueOf(inv.state) != \"正常\") {\n        return\n    }\n\n    try {\n        def invoiceTime = LocalDateTime.parse(String.valueOf(inv.invoiceTime), DateTimeFormatter.ofPattern(\"yyyy-MM-dd HH:mm:ss\"))\n        if (!isInPrevious12Months(appDate, invoiceTime)) {\n            return\n        }\n\n        def amount = parseMoney(inv.jshjText)\n        sum = sum.add(amount)\n        matched++\n        matchedInvoices << [\n            sign: inv.sign,\n            state: inv.state,\n            invoiceTime: inv.invoiceTime,\n            jshj: amount\n        ]\n    } catch (Exception ignored) {\n    }\n}\n\ndef processed = [\n    indicatorCode: \"inv_f1_12m_down_sale_jshj_sum_teach\",\n    saleJshjSum: sum.setScale(5, RoundingMode.HALF_UP),\n    appDate: parsed.appDate,\n    invoiceTotal: total,\n    invoiceMatched: matched,\n    matchedInvoices: matchedInvoices\n]\n\ndef validationDetail = [\n    invoiceTotal: total,\n    invoiceMatched: matched,\n    matchedInvoices: matchedInvoices\n]\n\ndef validationResult = \"发票总数=${total}, 命中数=${matched}\"\ndef now = LocalDateTime.now()\n\ndef sql = \"\"\"\n    insert into data_processing\n    (task_id, execution_id, analysis_id, taxpayer_id_no, enterprise_name, status, validation_result, processed_data, validation_detail, error_message, process_time, processing_time, create_time, update_time)\n    values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n\"\"\"\n\ndef keyHolder = new GeneratedKeyHolder()\njdbcTemplate.update({ con ->\n    def ps = con.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)\n    ps.setLong(1, taskId as Long)\n    ps.setLong(2, executionId as Long)\n    ps.setLong(3, stepContext.analysisId as Long)\n    ps.setString(4, taxpayerIdNo)\n    ps.setString(5, enterpriseName)\n    ps.setInt(6, 1)\n    ps.setString(7, validationResult)\n    ps.setString(8, objectMapper.writeValueAsString(processed))\n    ps.setString(9, objectMapper.writeValueAsString(validationDetail))\n    ps.setString(10, null)\n    ps.setTimestamp(11, Timestamp.valueOf(now))\n    ps.setTimestamp(12, Timestamp.valueOf(now))\n    ps.setTimestamp(13, Timestamp.valueOf(now))\n    ps.setTimestamp(14, Timestamp.valueOf(now))\n    return ps\n}, keyHolder)\n\ndef processingId = keyHolder.key?.longValue()\nif (processingId == null) {\n    throw new RuntimeException(\"插入 data_processing 失败，未获取到主键\")\n}\n\nstepContext.processed = processed\nstepContext.processingId = processingId\n\nreturn [\n    processingId: processingId,\n    indicatorCode: processed.indicatorCode,\n    invoiceMatched: matched,\n    saleJshjSum: processed.saleJshjSum\n]',NULL,NULL,'2026-03-26 14:32:25','2026-03-26 14:32:25'),(63,5,4,'保存最终业务结果','ACTION','Groovy','import java.sql.Timestamp\nimport java.time.LocalDateTime\n\ndef processed = stepContext.processed ?: stepContext.step_3\nif (processed == null) {\n    throw new RuntimeException(\"未获取到第三步加工结果\")\n}\nif (stepContext.processingId == null) {\n    throw new RuntimeException(\"缺少 processingId\")\n}\n\ndef now = LocalDateTime.now()\ndef businessData = [\n    taskId: taskId,\n    taskCode: taskCode,\n    executionId: executionId,\n    executionCode: executionCode,\n    taxpayerIdNo: taxpayerIdNo,\n    enterpriseName: enterpriseName,\n    processCode: processCode,\n    robotCode: robotCode,\n    generatedAt: now.toString(),\n    result: processed\n]\n\njdbcTemplate.update(\"\"\"\n    insert into data_business_final\n    (task_id, execution_id, processing_id, taxpayer_id_no, enterprise_name, tax_area_id, indicator_code, data_status, business_data, create_time, update_time, tax_area_name)\n    values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n\"\"\",\n        taskId,\n        executionId,\n        stepContext.processingId,\n        taxpayerIdNo,\n        enterpriseName,\n        null,\n        processed.indicatorCode,\n        1,\n        objectMapper.writeValueAsString(businessData),\n        Timestamp.valueOf(now),\n        Timestamp.valueOf(now),\n        null\n)\n\nstepContext.finalBusinessData = businessData\n\nreturn [\n    executionId: executionId,\n    processingId: stepContext.processingId,\n    indicatorCode: processed.indicatorCode,\n    saved: true\n]',NULL,NULL,'2026-03-26 14:32:25','2026-03-26 14:32:25'),(64,6,1,'01','ACTION','Groovy','import org.springframework.jdbc.support.GeneratedKeyHolder\nimport java.sql.Statement\nimport java.sql.Timestamp\nimport java.time.LocalDateTime\n\ndef now = LocalDateTime.now()\ndef payload = [\n    source: \"status-test\",\n    taxpayerIdNo: taxpayerIdNo,\n    enterpriseName: enterpriseName,\n    collectedAt: now.toString(),\n    invoices: [\n        [sign: \"销项\", state: \"正常\", invoiceTime: \"2024-01-15 10:30:00\", jshjText: \"123,456.79\"],\n        [sign: \"销项\", state: \"正常\", invoiceTime: \"2024-02-20 14:20:00\", jshjText: \"234,567.89\"]\n    ]\n]\n\ndef sql = \"\"\"\n    insert into data_collection\n    (task_id, execution_id, taxpayer_id_no, enterprise_name, source_name, status, raw_data, error_message, collect_time, collection_time, create_time, update_time)\n    values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n\"\"\"\n\ndef keyHolder = new GeneratedKeyHolder()\njdbcTemplate.update({ con ->\n    def ps = con.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)\n    ps.setLong(1, taskId as Long)\n    ps.setLong(2, executionId as Long)\n    ps.setString(3, taxpayerIdNo)\n    ps.setString(4, enterpriseName)\n    ps.setString(5, \"status-test-source\")\n    ps.setInt(6, collectionStatusProcessing)\n    ps.setString(7, objectMapper.writeValueAsString(payload))\n    ps.setString(8, null)\n    ps.setTimestamp(9, Timestamp.valueOf(now))\n    ps.setTimestamp(10, Timestamp.valueOf(now))\n    ps.setTimestamp(11, Timestamp.valueOf(now))\n    ps.setTimestamp(12, Timestamp.valueOf(now))\n    ps\n}, keyHolder)\n\ndef collectionId = keyHolder.key?.longValue()\nif (collectionId == null) {\n    throw new RuntimeException(\"插入 data_collection 失败\")\n}\n\nstepContext.collectionId = collectionId\nstepContext.collected = payload\n\nreturn [\n    collectionId: collectionId,\n    status: collectionStatusProcessing,\n    message: \"采集记录已写入处理中\"\n]',NULL,NULL,'2026-03-27 09:39:10','2026-03-27 09:39:10'),(65,6,2,'02','ACTION','Groovy','import org.springframework.jdbc.support.GeneratedKeyHolder\nimport java.sql.Statement\nimport java.sql.Timestamp\nimport java.time.LocalDateTime\n\ndef payload = stepContext.collected\nif (payload == null) {\n    throw new RuntimeException(\"缺少 step1 采集结果\")\n}\nif (stepContext.collectionId == null) {\n    throw new RuntimeException(\"缺少 collectionId\")\n}\n\ndef invoices = payload.invoices.collect { row ->\n    [\n        sign: row.sign,\n        state: row.state,\n        invoiceTime: row.invoiceTime,\n        jshjText: row.jshjText,\n        normalizedAmount: row.jshjText.replace(\",\", \"\")\n    ]\n}\n\ndef parsed = [\n    taxpayerIdNo: payload.taxpayerIdNo,\n    enterpriseName: payload.enterpriseName,\n    invoiceCount: invoices.size(),\n    invoices: invoices\n]\n\ndef now = LocalDateTime.now()\ndef sql = \"\"\"\n    insert into data_analysis\n    (task_id, execution_id, collection_id, taxpayer_id_no, enterprise_name, status, extracted_field_count, rule_name, parsed_data, error_message, analysis_time, create_time, update_time)\n    values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n\"\"\"\n\ndef keyHolder = new GeneratedKeyHolder()\njdbcTemplate.update({ con ->\n    def ps = con.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)\n    ps.setLong(1, taskId as Long)\n    ps.setLong(2, executionId as Long)\n    ps.setLong(3, stepContext.collectionId as Long)\n    ps.setString(4, taxpayerIdNo)\n    ps.setString(5, enterpriseName)\n    ps.setInt(6, analysisStatusProcessing)\n    ps.setInt(7, invoices.size())\n    ps.setString(8, \"状态测试解析规则\")\n    ps.setString(9, objectMapper.writeValueAsString(parsed))\n    ps.setString(10, null)\n    ps.setTimestamp(11, Timestamp.valueOf(now))\n    ps.setTimestamp(12, Timestamp.valueOf(now))\n    ps.setTimestamp(13, Timestamp.valueOf(now))\n    ps\n}, keyHolder)\n\ndef analysisId = keyHolder.key?.longValue()\nif (analysisId == null) {\n    throw new RuntimeException(\"插入 data_analysis 失败\")\n}\n\nstepContext.analysisId = analysisId\nstepContext.parsed = parsed\n\nreturn [\n    analysisId: analysisId,\n    status: analysisStatusProcessing,\n    message: \"解析记录已写入处理中\"\n]',NULL,NULL,'2026-03-27 09:39:10','2026-03-27 09:39:10'),(66,6,3,'03','ACTION','Groovy','import org.springframework.jdbc.support.GeneratedKeyHolder\nimport java.sql.Statement\nimport java.sql.Timestamp\nimport java.time.LocalDateTime\nimport java.math.BigDecimal\n\ndef parsed = stepContext.parsed\nif (parsed == null) {\n    throw new RuntimeException(\"缺少 step2 解析结果\")\n}\nif (stepContext.analysisId == null) {\n    throw new RuntimeException(\"缺少 analysisId\")\n}\n\nBigDecimal sum = BigDecimal.ZERO\n(parsed.invoices ?: []).each { row ->\n    sum = sum.add(new BigDecimal(String.valueOf(row.normalizedAmount)))\n}\n\ndef processed = [\n    indicatorCode: \"status_test_sum\",\n    invoiceCount: parsed.invoiceCount,\n    totalAmount: sum\n]\n\ndef validation = [\n    passed: true,\n    message: \"状态测试数据\"\n]\n\ndef now = LocalDateTime.now()\ndef sql = \"\"\"\n    insert into data_processing\n    (task_id, execution_id, analysis_id, taxpayer_id_no, enterprise_name, status, validation_result, processed_data, validation_detail, error_message, process_time, processing_time, create_time, update_time)\n    values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n\"\"\"\n\ndef keyHolder = new GeneratedKeyHolder()\njdbcTemplate.update({ con ->\n    def ps = con.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)\n    ps.setLong(1, taskId as Long)\n    ps.setLong(2, executionId as Long)\n    ps.setLong(3, stepContext.analysisId as Long)\n    ps.setString(4, taxpayerIdNo)\n    ps.setString(5, enterpriseName)\n    ps.setInt(6, processingStatusProcessing)\n    ps.setString(7, \"通过\")\n    ps.setString(8, objectMapper.writeValueAsString(processed))\n    ps.setString(9, objectMapper.writeValueAsString(validation))\n    ps.setString(10, null)\n    ps.setTimestamp(11, Timestamp.valueOf(now))\n    ps.setTimestamp(12, Timestamp.valueOf(now))\n    ps.setTimestamp(13, Timestamp.valueOf(now))\n    ps.setTimestamp(14, Timestamp.valueOf(now))\n    ps\n}, keyHolder)\n\ndef processingId = keyHolder.key?.longValue()\nif (processingId == null) {\n    throw new RuntimeException(\"插入 data_processing 失败\")\n}\n\nstepContext.processingId = processingId\nstepContext.processed = processed\n\nreturn [\n    processingId: processingId,\n    status: processingStatusProcessing,\n    message: \"加工记录已写入处理中\"\n]',NULL,NULL,'2026-03-27 09:39:10','2026-03-27 09:39:10'),(67,6,4,'04','ACTION','Groovy','import java.sql.Timestamp\nimport java.time.LocalDateTime\n\ndef processed = stepContext.processed\nif (processed == null) {\n    throw new RuntimeException(\"缺少 step3 加工结果\")\n}\nif (stepContext.processingId == null) {\n    throw new RuntimeException(\"缺少 processingId\")\n}\n\ndef now = LocalDateTime.now()\ndef businessData = [\n    taskId: taskId,\n    executionId: executionId,\n    taxpayerIdNo: taxpayerIdNo,\n    enterpriseName: enterpriseName,\n    result: processed,\n    generatedAt: now.toString()\n]\n\njdbcTemplate.update(\"\"\"\n    insert into data_business_final\n    (task_id, execution_id, processing_id, taxpayer_id_no, enterprise_name, tax_area_id, indicator_code, tax_area_name, data_status, business_data, create_time, update_time)\n    values (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)\n\"\"\",\n    taskId,\n    executionId,\n    stepContext.processingId,\n    taxpayerIdNo,\n    enterpriseName,\n    null,\n    processed.indicatorCode,\n    null,\n    businessDataStatusAvailable,\n    objectMapper.writeValueAsString(businessData),\n    Timestamp.valueOf(now),\n    Timestamp.valueOf(now)\n)\n\nreturn [\n    saved: true,\n    executionId: executionId,\n    processingId: stepContext.processingId\n]',NULL,NULL,'2026-03-27 09:39:10','2026-03-27 09:39:10'),(68,7,1,'01','ACTION','Groovy','import java.time.LocalDateTime\n\ndef totalSeconds = 70\ndef checkpoints = [5, 10, 20, 30, 40, 50, 60, 70]\n\nprintln \"开始长任务测试\"\nprintln \"taskId=\" + taskId\nprintln \"executionId=\" + executionId\nprintln \"robotId=\" + robotId\nprintln \"开始时间=\" + LocalDateTime.now()\n\nstepContext.longRunningTest = [\n    taskId: taskId,\n    executionId: executionId,\n    robotId: robotId,\n    startedAt: LocalDateTime.now().toString(),\n    totalSeconds: totalSeconds\n]\n\nfor (int i = 1; i <= totalSeconds; i++) {\n    Thread.sleep(1000)\n\n    if (checkpoints.contains(i)) {\n        println \"长任务进行中: ${i}/${totalSeconds} 秒, 当前时间=\" + LocalDateTime.now()\n        stepContext.longRunningTest.progressSeconds = i\n        stepContext.longRunningTest.lastCheckpointAt = LocalDateTime.now().toString()\n    }\n}\n\nstepContext.longRunningTest.finishedAt = LocalDateTime.now().toString()\nstepContext.longRunningTest.finished = true\n\nprintln \"长任务结束\"\nprintln \"结束时间=\" + LocalDateTime.now()\n\nreturn [\n    message: \"长任务执行完成\",\n    taskId: taskId,\n    executionId: executionId,\n    robotId: robotId,\n    durationSeconds: totalSeconds\n]',NULL,NULL,'2026-03-27 10:21:12','2026-03-27 10:21:12');

